import {rectifier} from './rectifier-filter.mjs';
import {engineState,pressState,pneumaticState} from '../machines/model.mjs';
export function state(id,values,u){const [a,b=0,c=0]=values,theta=u*2*Math.PI,area=Math.PI*.04**2/4,ann=area*.75;let m={u,theta,values},read=[];const r=(es,en,v,unit)=>read.push({es,en,value:v,unit});
if(id==='torque'){m.torque=a*b*Math.sin(c*Math.PI/180);r('Par','Torque',m.torque,'N·m');r('Brazo perpendicular','Perpendicular arm',b*Math.sin(c*Math.PI/180),'m');}
else if(id==='transmission'){m.ratio=18/a;r('Salida con entrada 120 rpm','Output at 120 rpm input',120*m.ratio,'rpm');r('Par ideal salida','Ideal output torque',b/m.ratio,'N·m');}
else if(id==='fourstroke'){Object.assign(m,engineState(u*.999999));r('Cigüeñal','Crankshaft',u*720,'°');r('Ciclos por segundo','Cycles per second',a/120,'Hz');}
else if(id==='thermal'){m.temp=20+a/b*(1-Math.exp(-b*u*600/1000));r('Tiempo','Time',u*600,'s');r('Temperatura','Temperature',m.temp,'°C');r('Equilibrio','Equilibrium',20+a/b,'°C');r('Calor al ambiente','Heat to room',b*(m.temp-20),'W');r('Potencia que calienta el bloque','Net heating power',a-b*(m.temp-20),'W');}
else if(id==='nostart'){m.current=a/(.05+b);m.output=m.current*.05;m.input=a;r('Corriente modelo resistivo','Resistive model current',m.current,'A');r('Tensión motor','Motor voltage',m.output,'V');r('Caída en masa','Ground drop',m.current*b,'V');}
else if(id==='ohm'){m.input=a;m.output=a;m.current=a/b;r('Corriente','Current',1000*m.current,'mA');r('Potencia resistencia','Resistor power',a*a/b,'W');}
else if(id==='ac'){m.input=a*Math.sin(theta);m.output=m.input;m.current=m.input/1000;r('Instantánea','Instantaneous',m.input,'V');r('RMS','RMS',a/Math.SQRT2,'V');r('Periodo','Period',1000/b,'ms');r('Potencia instantánea','Instantaneous power',m.input*m.current*1000,'mW');}
else if(id==='rectifier'){Object.assign(m,rectifier(values,u));r('Sin filtro','Unfiltered',m.bare,'V');r('Después del filtro','After filter',m.output,'V');r('En la carga','Across load',m.loadVoltage,'V');r('Entrada mínima para regular','Minimum input for regulation',m.enabled?9:0,'V');r('Rizado del filtro','Filter ripple (p-p)',m.ripple,'V');r('Corriente de carga','Load current',1000*m.current,'mA');r('Carga almacenada','Stored charge',1000*m.charge,'mC');}
else if(id==='opamp'){m.input=a*Math.sin(theta);m.output=Math.max(-12,Math.min(12,m.input*b));Object.assign(m,{t:u*2,angle:theta,a:b,effectiveGain:b,rail:12});r('Entrada','Input',m.input,'V');r('Salida','Output',m.output,'V');r('Pico solicitado','Requested peak',a*b,'V');}
else if(id==='threephase'){Object.assign(m,{fieldAngle:theta,rotorAngle:theta*(1-b/100),currents:[0,1,2].map(i=>Math.sin(theta-i*2*Math.PI/3))});r('Campo, motor de 2 polos','Field, 2-pole motor',60*a,'rpm');r('Rotor','Rotor',60*a*(1-b/100),'rpm');m.currents.forEach((v,i)=>r('Fase '+(i+1),'Phase '+(i+1),v,'p.u.'));
  // Separate balanced star-source example with a 10 V phase peak.
  m.phaseVoltages = [0, 1, 2].map(phase => 10 * Math.sin(theta - phase * 2 * Math.PI / 3));
  m.lineVoltage = m.phaseVoltages[0] - m.phaseVoltages[1];
  r('V entre A y B','Voltage across A and B',m.lineVoltage,'V');
  r('RMS fase','Phase RMS',10/Math.SQRT2,'V');
  r('RMS línea','Line RMS',10*Math.sqrt(3/2),'V');}
else if(id==='pascal'){Object.assign(m,pressState(u*.5,a,b));r('Presión','Pressure',m.pressure/1e5,'bar');r('Fuerza salida','Output force',m.outputForce,'N');r('Entrada','Input travel',m.inputMM,'mm');r('Salida','Output travel',m.outputMM,'mm');}
else if(id==='relief'){const opening=Math.max(0,Math.min(1,(a-b)/(.2*b))),ret=6*opening;Object.assign(m,{opening,returnFlow:ret,cylinderFlow:6-ret,pumpFlow:6,x:u*(1-opening),t:u*4,heat:a*ret/600*1000});r('Apertura','Opening',opening*100,'%');r('Al cilindro','To cylinder',6-ret,'L/min');r('Al tanque','To tank',ret,'L/min');r('Calor retorno','Return heat',m.heat,'W');}
else if(['flow','power','hydrodiagnosis'].includes(id)){const useful=id==='hydrodiagnosis'?Math.max(0,a-b):a,A=id==='flow'?b:20,speed=useful*1000/60/A;Object.assign(m,{x:Math.min(1,u*2*speed/10),leak:id==='hydrodiagnosis'?b:0,advance:true,speed,inlet:a,useful,t:u*2});r('Velocidad','Speed',speed,'cm/s');r('Caudal útil','Useful flow',useful,'L/min');r('Posición a t = '+(u*2).toFixed(1)+' s','Position at t = '+(u*2).toFixed(1)+' s',m.x*100,'mm');if(id==='power')r('Pérdida en restricción','Restriction loss',a*b/600*1000,'W');}
else if(id==='air'){m.volume=a;m.absolute=2/a;m.gauge=m.absolute-1;r('Presión absoluta','Absolute pressure',m.absolute,'bar');r('Presión manométrica','Gauge pressure',m.gauge,'bar');r('p × V','p × V',2,'bar·L');}
else {const p=id==='airchain'?Math.max(0,Math.min(b,a-c)):a,back=['cylinderforce','pneudiagnosis'].includes(id)?b:0;Object.assign(m,pneumaticState(u*.999999,p,40));m.pA=m.advance?p:back;m.pB=m.advance?back:p;m.gaugePressure=p;m.force=m.advance?p*1e5*area-back*1e5*ann:p*1e5*ann-back*1e5*area;r('Cámara A','Chamber A',m.pA,'bar');r('Cámara B','Chamber B',m.pB,'bar');r('Fuerza en sentido ordenado','Force in commanded direction',m.force,'N');r('Posición prescrita','Prescribed position',m.x*100,'mm');}
return {...m,read};}
